Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define ULL unsigned LL
#define PII pair<int,int>
#define PB push_back
#define MP make_pair
#define INF 1000000000
#define MOD 1000000007

int distArr[15][15][15][15];
int cap[400][400];
char scien[20][20];
char reac[20][20];
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
int iterCount = 3;
int visited[400];

int n, t;
int flowAug(int cnode, int dest, int bneck) {
    if (cnode == dest) return bneck;
    if (visited[cnode] == iterCount) return 0;
    visited[cnode] = iterCount;
    for (int i = 0; i <= dest; i++) {
        if (cap[cnode][i] > 0) {
            int pushed = flowAug(i, dest, min(bneck, cap[cnode][i]));
            if (pushed > 0) {
                cap[cnode][i] -= pushed;
                cap[i][cnode] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int nodeIdx(int x, int y) {
    return (x - 1) * n + y - 1;
}

int reachStates[13][13], tempStates[13][13];

void propagate(int val) {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            tempStates[i][j] = reachStates[i][j];

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (tempStates[i][j] == val) {
                for (int d = 0; d < 4; d++) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (ni > 0 && nj > 0 && ni <= n && nj <= n && reachStates[ni][nj] < val && scien[ni][nj] != 'Y') {
                        reachStates[ni][nj] = val;
                    }
                }
            }
        }
    }
}

bool checkReach(int sx, int sy, int tx, int ty, int ix, int iy) {
    memset(reachStates, 0, sizeof(reachStates));
    reachStates[sx][sy] = 1;
    reachStates[ix][iy] = 2;
    for (int i = 0; i < 100; i++) {
        propagate(1);
        if (reachStates[tx][ty] == 1) return true;
        propagate(2);
        if (reachStates[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    int infX, infY;
    memset(distArr, 1, sizeof(distArr));
    cin >> n >> t;
    for (int i = 1; i <= n; i++) {
        scanf(" %s", scien[i] + 1);
        for (int j = 1; j <= n; j++) {
            distArr[i][j][i][j] = 0;
            if (scien[i][j] == 'Z') {
                infX = i; infY = j;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        scanf(" %s", reac[i] + 1);
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            for (int d = 0; d < 4; d++) {
                int ni = i + dx[d], nj = j + dy[d];
                if (ni > 0 && ni <= n && nj > 0 && nj <= n) {
                    if (scien[i][j] != 'Y' && scien[ni][nj] != 'Y') {
                        distArr[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }
    for (int ki = 1; ki <= n; ki++) {
        for (int kj = 1; kj <= n; kj++) {
            for (int ii = 1; ii <= n; ii++) {
                for (int ij = 1; ij <= n; ij++) {
                    for (int ji = 1; ji <= n; ji++) {
                        for (int jj = 1; jj <= n; jj++) {
                            distArr[ii][ij][ji][jj] = min(
                                distArr[ii][ij][ji][jj],
                                distArr[ii][ij][ki][kj] + distArr[ki][kj][ji][jj]
                            );
                        }
                    }
                }
            }
        }
    }
    int srcNode = n * n * 2 + 1;
    int sinkNode = n * n * 2 + 2;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (isdigit(scien[i][j])) {
                cap[srcNode][nodeIdx(i, j)] = scien[i][j] - '0';
            }
            if (isdigit(reac[i][j])) {
                cap[n * n + nodeIdx(i, j)][sinkNode] = reac[i][j] - '0';
            }
            if (isdigit(scien[i][j])) {
                for (int ki = 1; ki <= n; ki++) {
                    for (int kj = 1; kj <= n; kj++) {
                        if (scien[i][j] > '0' && reac[ki][kj] > '0') {
                            if (isdigit(reac[ki][kj]) && distArr[i][j][ki][kj] <= t && checkReach(i, j, ki, kj, infX, infY)) {
                                cap[nodeIdx(i, j)][n * n + nodeIdx(ki, kj)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }
    int totalFlow = 0, flowVal;
    while ((flowVal = flowAug(srcNode, sinkNode, 1000)) > 0) {
        totalFlow += flowVal;
        iterCount++;
    }
    cout << totalFlow << endl;
    return 0;
}
